        numbers: {
          'Total spending need': '$80,000/year',
          'Guaranteed income (SS + annuity)': '$52,000/year',
          'Portfolio withdrawal need': '$28,000/year',
          'Investment portfolio': '$600,000',
          'Discretionary withdrawal rate': '4.7%',
        },
